from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urljoin, urlparse
import hashlib, json, re

source = 'https://novatize.com/en-us'
raw = Path('products/services/catalogue-migration-agency-pilot/raw/novatize-home.html').read_bytes()

class Homepage(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.ignored = 0
        self.fragments = []
        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag in {'script', 'style', 'template'}:
            self.ignored += 1
        if tag == 'a' and not self.ignored:
            href = dict(attrs).get('href') or ''
            if href:
                link = urlparse(urljoin(source, href))
                if link.hostname in {'novatize.com', 'www.novatize.com'} and re.search(r'contact|migration|services|shopify', link.path, re.I):
                    self.links.append(link._replace(query='', fragment='').geturl())

    def handle_endtag(self, tag):
        if tag in {'script', 'style', 'template'} and self.ignored:
            self.ignored -= 1

    def handle_data(self, value):
        text = ' '.join(value.split())
        if not self.ignored and text:
            self.fragments.append(text)

page = Homepage()
page.feed(raw.decode('utf-8'))
terms = re.compile(r'migrat|catalog|product data|Québec|Quebec|Montréal|Montreal|Canada', re.I)
excerpts = list(dict.fromkeys(line for line in page.fragments if len(line) <= 650 and terms.search(line)))[:24]
result = {'source': source, 'capture_task': 'TASK-179566202800', 'sha256': hashlib.sha256(raw).hexdigest(), 'candidate_text_fragments': excerpts, 'first_party_link_pointers': sorted(set(page.links))[:24], 'scope': 'Static homepage extract for the existing catalogue handoff. Read excerpts in context before qualification. Links are pointers. This establishes neither invited subcontracting nor operator authorization.'}
output = Path('products/services/catalogue-migration-agency-pilot/director-novatize-homepage-extract.json')
output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'excerpt_count': len(excerpts), 'pointer_count': len(result['first_party_link_pointers']), 'sha256': result['sha256'], 'artifact': str(output)}))
